(()=>{
const en=document.documentElement.lang==='en',t=(ar,e)=>en?e:ar;
const dialog=document.createElement('dialog');dialog.className='lead-dialog';dialog.setAttribute('aria-labelledby','trial-title');
const fields=[['name','الاسم الكامل','Full name','text','name'],['organization','اسم المدرسة أو الجهة','School or organization','text','organization'],['email','البريد الإلكتروني','Email','email','email'],['phone','رقم الجوال مع رمز الدولة','Phone with country code','tel','tel']];
dialog.innerHTML='<button class="lead-close" type="button" aria-label="'+t('إغلاق','Close')+'">×</button><span class="lead-tag">GOEGSA · '+t('تجربة مجانية 14 يومًا','Free 14-day trial')+'</span><h2 id="trial-title">'+t('عرّفنا بمدرستك، وابدأ التجربة.','Tell us about your school. Start your trial.')+'</h2><p>'+t('ستفتح رسالة جاهزة؛ راجعها وأرسلها، ثم نزّل النسخة.','A prepared message will open; review and send it, then download the trial.')+'</p><form class="lead-form">'+fields.map(([name,ar,eng,type,autocomplete])=>'<label>'+t(ar,eng)+'<input name="'+name+'" type="'+type+'" autocomplete="'+autocomplete+'" required maxlength="160" '+(type==='tel'?'pattern="[+0-9 ().-]{7,30}" dir="ltr" placeholder="+966 5X XXX XXXX"':type==='email'?'dir="ltr"':'minlength="2"')+'></label>').join('')+'<fieldset class="trial-channel"><legend>'+t('طريقة الإرسال','Send via')+'</legend><label><input name="channel" type="radio" value="email" checked>'+t('البريد الإلكتروني','Email')+'</label><label><input name="channel" type="radio" value="whatsapp">'+t('واتساب','WhatsApp')+'</label></fieldset><label class="lead-check"><input name="marketing" type="checkbox"><span>'+t('أوافق على تلقي عروض GOEGSA والمتابعة التسويقية عبر البريد والجوال وواتساب (اختياري).','I agree to GOEGSA offers and marketing follow-ups by email, phone and WhatsApp (optional).')+'</span></label><small>'+t('ستُضمّن بياناتك في الرسالة إلى GOEGSA. يمكنك طلب إيقاف التسويق في أي وقت.','Your details will be included in your message to GOEGSA. You can ask us to stop marketing at any time.')+'</small><button class="btn" type="submit">'+t('إرسال وفتح التنزيل','Send & unlock download')+'</button><div class="lead-status" role="status" aria-live="polite"></div><a class="btn trial-download" hidden>'+t('تنزيل البرنامج الآن','Download the program now')+'</a></form>';
document.body.append(dialog);const privacyNote=document.createElement('p');privacyNote.className='privacy-form-note';const privacyLink=document.createElement('a');privacyLink.href=(en?'/en/':'/')+'privacy/';privacyLink.target='_blank';privacyLink.rel='noopener noreferrer';privacyLink.textContent=t('سياسة الخصوصية','Privacy policy');privacyNote.append(privacyLink);dialog.querySelector('form').prepend(privacyNote);dialog.querySelector('.lead-close').onclick=()=>dialog.close();
document.addEventListener('click',e=>{if(e.target.closest('[data-simple-trial]')){e.preventDefault();dialog.showModal();}});
dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const message=[t('طلب تجربة نظام إدارة المدارس','School Management System trial request'),...fields.map(([name,ar,eng])=>t(ar,eng)+': '+data.get(name)),t('الموافقة التسويقية: ','Marketing consent: ')+(data.get('marketing')==='on'?t('نعم','Yes'):t('لا','No'))].join('\n');const href=data.get('channel')==='whatsapp'?'https://wa.me/'+SITE_CONFIG.whatsapp.number+'?text='+encodeURIComponent(message):'mailto:goegsa.business@gmail.com?subject='+encodeURIComponent(t('طلب نسخة تجريبية من GOEGSA','GOEGSA trial request'))+'&body='+encodeURIComponent(message);
const a=document.createElement('a');a.href=href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=t('فتح الرسالة مجددًا','Open the message again');document.body.append(a);a.click();dialog.querySelector('.lead-status').replaceChildren(a);const notice=document.createElement('p');notice.textContent=t('راجع الرسالة وأرسلها. يمكنك الآن تنزيل البرنامج.','Review and send your message. You can now download the program.');dialog.querySelector('.lead-status').prepend(notice);const download=dialog.querySelector('.trial-download');download.href=SITE_CONFIG.products.school.trial.downloadUrl;download.target='_blank';download.rel='noopener noreferrer';download.hidden=false;});
})();